class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        m = len(grid)
        n = len(grid[0])

        # Traverse each row
        for r in range(m):
            # Determine the starting column and step based on row parity
            # Even rows (0, 2, 4...) traverse Right and visit even columns (0, 2, 4...)
            # Odd rows (1, 3, 5...) traverse Left and visit odd columns (1, 3, 5...)
            # Based on analysis of examples, the selection logic is:
            # Even rows: visit indices 0, 2, 4, ...
            # Odd rows: visit indices 1, 3, 5, ...

            if r % 2 == 0:
                # Even row: Traverse Right, visit even column indices
                for c in range(0, n, 2):
                    result.append(grid[r][c])
            else:
                # Odd row: Traverse Left, visit odd column indices
                for c in range(1, n, 2):
                    result.append(grid[r][c])

        return result

class Solution:
    def countPartitions(self, nums: List[int]) -> int:
        # Calculate the total sum of the array
        total_sum = sum(nums)

        # If the total sum is even, then (sum_left - sum_right) is even for all partitions.
        # If the total sum is odd, then (sum_left - sum_right) is odd for all partitions.
        # The number of partitions is the number of indices i from 0 to n-2, which is n-1.
        if total_sum % 2 == 0:
            return len(nums) - 1
        else:
            return 0

class Solution:
    def maxDifference(self, s: str) -> int:
        # Dictionary to store the frequency of each character
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1

        # Initialize variables to track the maximum odd frequency and minimum even frequency
        # max_odd will store the highest frequency among characters with odd counts
        # min_even will store the lowest frequency among characters with even counts
        max_odd = -1
        min_even = float('inf')

        # Iterate through the frequencies of all unique characters present in the string
        for count in freq.values():
            if count % 2 == 1:
                # If frequency is odd, update max_odd if this frequency is greater than the current max_odd
                if count > max_odd:
                    max_odd = count
            else:
                # If frequency is even, update min_even if this frequency is smaller than the current min_even
                if count < min_even:
                    min_even = count

        # Calculate and return the maximum difference
        # The problem asks for (Odd Frequency) - (Even Frequency)
        return max_odd - min_even

