class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # Iterate over all possible start indices for a substring of length k
        for i in range(n - k + 1):
            # Check if the substring s[i:i+k] consists of only one distinct character.
            # We verify that all characters in the slice are equal to the first character s[i].
            if all(c == s[i] for c in s[i:i+k]):
                # Check the character immediately before the substring.
                # If it exists (i > 0) and is the same as the substring character, this substring is invalid.
                if i > 0 and s[i-1] == s[i]:
                    continue
                # Check the character immediately after the substring.
                # If it exists (i + k < n) and is the same as the substring character, this substring is invalid.
                if i + k < n and s[i+k] == s[i]:
                    continue
                # If all conditions are met, we found a valid substring.
                return True
        # If no such substring exists after checking all possibilities, return false.
        return False

