class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        # Dictionary to store the count of subarrays for each number.
        # The key is the number, and the value is the number of subarrays it appears in.
        count = {}
        n = len(nums)

        # Iterate through all possible subarrays of size k.
        # There are n - k + 1 such subarrays.
        for i in range(n - k + 1):
            # Identify unique numbers in the current subarray.
            # Using a set ensures that even if a number appears multiple times in a subarray,
            # it is only counted once for that subarray.
            unique_nums = set(nums[i : i + k])

            # Update the global count for each unique number found in this subarray.
            for num in unique_nums:
                if num not in count:
                    count[num] = 0
                count[num] += 1

        result = -1
        # Iterate through the counts to find the largest number that appears in exactly one subarray.
        for num, count_val in count.items():
            if count_val == 1:
                if num > result:
                    result = num

        return result

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # The total number of cells on the n x n deck is n * n.
        # Each cell can hold one container of weight w.
        # The maximum number of containers we can load is limited by two factors:
        # 1. The number of cells available on the deck (n * n).
        # 2. The ship's weight capacity (maxWeight // w).
        # Therefore, the result is the minimum of these two values.
        return min(n * n, maxWeight // w)

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)

        # Build adjacency list for the graph
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct integers common to both properties[i] and properties[j]
                common = set(properties[i]) & set(properties[j])
                if len(common) >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Count connected components using BFS
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                # Start BFS from this node
                stack = [i]
                visited[i] = True
                while stack:
                    node = stack.pop()
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)

        return components

class Solution:
    def minCosts(self, cost: List[int]) -> List[int]:
        n = len(cost)
        answer = [0] * n
        for i in range(n):
            if i == 0:
                answer[i] = cost[i]
            else:
                answer[i] = min(cost[i], answer[i-1])
        return answer

