class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        n = len(nums)
        max_diff = 0
        for i in range(n):
            # Calculate the absolute difference between the current element and its next neighbor.
            # In a circular array, the next element for the last index (n-1) is the first element (0).
            # This is handled by using the modulo operator (i + 1) % n.
            diff = abs(nums[i] - nums[(i + 1) % n])
            if diff > max_diff:
                max_diff = diff
        return max_diff

