class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)
        for i in range(n):
            is_good = True

            # Check if left neighbor index i - k exists and if nums[i] is strictly greater than nums[i - k]
            # If i - k < 0, the index does not exist, so we don't check this condition.
            if i >= k and nums[i] <= nums[i - k]:
                is_good = False

            # Check if right neighbor index i + k exists and if nums[i] is strictly greater than nums[i + k]
            # If i + k >= n, the index does not exist, so we don't check this condition.
            if i + k < n and nums[i] <= nums[i + k]:
                is_good = False

            if is_good:
                total_sum += nums[i]

        return total_sum
